INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3914346, 555132, 56828, '<td valign="top">This could be better if the right side of his ear and hat were not cut off.</td>', 'This could be better if the right side of his ear and hat were not cut off.', '2007-07-18 12:52:09.000000', NULL, 1),
(3914350, 555133, 56828, '<td valign="top">Prolly should have removed the people and the camera from the reflection in the glasses.  And way too much soft focus.</td>', 'Prolly should have removed the people and the camera from the reflection in the glasses.  And way too much soft focus.', '2007-07-18 12:53:27.000000', NULL, 1),
(3914359, 555382, 56828, '<td valign="top">This is a lovely photo.  I think catching the lghit from behind her instead of in front had a reverse effect.  Your model appears to have some Very gorgeous eyes, wish you could have the light there to bring them out more.  Still a great photo.</td>', 'This is a lovely photo.  I think catching the lghit from behind her instead of in front had a reverse effect.  Your model appears to have some Very gorgeous eyes, wish you could have the light there to bring them out more.  Still a great photo.', '2007-07-18 12:57:20.000000', NULL, 1),
(3914361, 556764, 56828, '<td valign="top">Face is out of focus.</td>', 'Face is out of focus.', '2007-07-18 12:57:44.000000', NULL, 1),
